{"path": "store/import_prefs_test.go", "old": "", "new": "package store

import "testing"

// An imported user without preferences must get the defaults, as AddUser
// gives them; otherwise u.Prefs is nil and notify dereferences it.
func TestImportUsersDefaultPrefs(t *testing.T) {
	s := newStore()
	if n := s.ImportUsers([]User{{ID: "u9", Name: "Cy", Token: "tok9"}}); n != 1 {
		t.Fatalf("ImportUsers added %d, want 1", n)
	}
	u, err := s.User("u9")
	if err != nil {
		t.Fatal(err)
	}
	if u.Prefs == nil {
		t.Fatal("imported user has nil Prefs, want the defaults")
	}
	if u.Prefs.Channel != "email" {
		t.Errorf("imported user channel = %q, want email", u.Prefs.Channel)
	}
	tu, err := s.UserByToken("tok9")
	if err != nil {
		t.Fatal(err)
	}
	if tu.Prefs == nil {
		t.Error("user found by token has nil Prefs")
	}
}
"}

